DO $migration$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.pm_gantt_save(text,uuid,text,jsonb,boolean)'::regprocedure) INTO definition; definition:=replace(definition,'IF _mode NOT IN (''quote'',''project'')','IF _mode=''quote'' AND NOT public.has_role(auth.uid(),''admin'') THEN RAISE EXCEPTION ''Forbidden'' USING ERRCODE=''42501''; END IF;'||chr(10)||'IF _mode NOT IN (''quote'',''project'')'); EXECUTE definition; END $migration$;
CREATE OR REPLACE FUNCTION public.pm_relative_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q uuid; BEGIN q:=CASE WHEN TG_OP='DELETE' THEN OLD.quote_id ELSE NEW.quote_id END; UPDATE quote_relative_schedules SET stage_offsets=coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'start',pm_relative_offset(start_date),'duration',pm_relative_offset(end_date)-pm_relative_offset(start_date)+1) ORDER BY id) FROM quote_stages WHERE quote_id=q),'[]'::jsonb),allocation_offsets=coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'stage_id',stage_id,'start',pm_relative_offset(start_date),'duration',pm_relative_offset(end_date)-pm_relative_offset(start_date)+1) ORDER BY id) FROM quote_allocations WHERE quote_id=q),'[]'::jsonb) WHERE quote_id=q; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER quote_stage_relative_delete AFTER DELETE ON public.quote_stages FOR EACH ROW EXECUTE FUNCTION public.pm_relative_sync();
CREATE TRIGGER quote_allocation_relative_delete AFTER DELETE ON public.quote_allocations FOR EACH ROW EXECUTE FUNCTION public.pm_relative_sync();